final class ChatEditSupport {
  static void check(boolean value,String why){VoiceSupport.check(value,why);}
  static String id(){return UUID.randomUUID().toString();}
  static String js(Instrumentation test,WebView web,String code)throws Exception{return VoiceSupport.evaluate(test,web,code);}
  static void wait(Instrumentation test,WebView web,String condition,String why)throws Exception{
    if(!VoiceSupport.waitFor(test,web,condition))throw new AssertionError(why+": "+js(test,web,"(()=>{const loaded=typeof state!=='undefined';return {ready:document.readyState,bootstrapped:loaded&&state.draftRestored,pendingCalls:typeof pendingCalls==='undefined'?null:pendingCalls.size,view:loaded?state.view:null,busy:loaded?state.busy:null,voiceState:loaded?state.voiceState:null,messageCount:loaded?state.messages.length:null,inputNonempty:!!document.getElementById('message-input')?.value.trim(),sendDisabled:document.getElementById('send')?.disabled,progress:document.getElementById('progress')?.textContent};})()"));
  }
  static void proof(Instrumentation test,String mode,JSONObject report)throws Exception{File folder=new File(test.getTargetContext().getExternalFilesDir(null),"chat-edit-proof");check(folder.isDirectory()||folder.mkdirs(),"Create chat-edit fixture evidence directory");try(OutputStream out=new FileOutputStream(new File(folder,mode+".json"))){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}}
  static void screenshot(Instrumentation test,WebView web,String name)throws Exception{js(test,web,"document.getElementById('toast').hidden=true;true");test.waitForIdleSync();Thread.sleep(400);File folder=new File(test.getTargetContext().getExternalFilesDir(null),"chat-edit-proof");folder.mkdirs();Bitmap image=test.getUiAutomation().takeScreenshot();check(image!=null,"Capture the asserted synthetic UI");try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){check(image.compress(Bitmap.CompressFormat.PNG,100,out),"Save fixture screenshot");}finally{image.recycle();}}
  static void tap(Instrumentation test,WebView web,String selector)throws Exception{
    js(test,web,"(()=>{const element=document.querySelector("+JSONObject.quote(selector)+");if(!element)throw new Error('Missing chat edit control');element.scrollIntoView({block:'center'});return true;})()");test.waitForIdleSync();Thread.sleep(160);
    JSONObject point=new JSONObject(js(test,web,"(()=>{const element=document.querySelector("+JSONObject.quote(selector)+"),r=element.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,hit=document.elementFromPoint(x,y),scroll=element.closest('.sheet-body'),s=scroll?.getBoundingClientRect();window.__chatEditTap={clicked:false};element.addEventListener('click',e=>window.__chatEditTap={clicked:true,trusted:e.isTrusted},{once:true,capture:true});return {x,y,w:innerWidth,h:innerHeight,onScreen:r.width>0&&r.height>0&&x>=0&&x<innerWidth&&y>=0&&y<innerHeight,hitAgrees:hit===element||element.contains(hit),hitId:hit?.id,disabled:!!element.disabled,rect:{top:r.top,bottom:r.bottom},scroller:s?{top:s.top,bottom:s.bottom,scrollTop:scroll.scrollTop}:null};})()"));
    if(!point.getBoolean("onScreen")||!point.getBoolean("hitAgrees")||point.getBoolean("disabled")){screenshot(test,web,"tap-hit-failure");throw new AssertionError("Chat-edit control is clipped/covered: "+selector+" "+point);}
    float[] location=new float[2];JSONObject nativeView=new JSONObject();test.runOnMainSync(()->{int[] origin=new int[2];web.getLocationOnScreen(origin);double scale=web.getWidth()/point.optDouble("w");location[0]=(float)(origin[0]+point.optDouble("x")*scale);location[1]=(float)(origin[1]+point.optDouble("y")*scale);android.graphics.Rect visible=new android.graphics.Rect();web.getWindowVisibleDisplayFrame(visible);try{nativeView.put("screenX",origin[0]).put("screenY",origin[1]).put("width",web.getWidth()).put("height",web.getHeight()).put("measuredWidth",web.getMeasuredWidth()).put("measuredHeight",web.getMeasuredHeight()).put("windowFocus",web.hasWindowFocus()).put("viewFocus",web.hasFocus()).put("shown",web.isShown()).put("scale",scale).put("pointerX",location[0]).put("pointerY",location[1]).put("visibleFrame",new JSONObject().put("left",visible.left).put("top",visible.top).put("right",visible.right).put("bottom",visible.bottom));}catch(Exception e){throw new IllegalStateException(e);}});long time=SystemClock.uptimeMillis();
    try{test.sendPointerSync(MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,location[0],location[1],0));test.sendPointerSync(MotionEvent.obtain(time,time+40,MotionEvent.ACTION_UP,location[0],location[1],0));}catch(SecurityException error){throw new AssertionError("Trusted chat-edit pointer injection rejected: selector="+selector+" point="+point+" nativeView="+nativeView+" reason="+error.getMessage(),error);}
    if(!VoiceSupport.waitFor(test,web,"window.__chatEditTap.clicked&&window.__chatEditTap.trusted")){screenshot(test,web,"tap-dispatch-failure");throw new AssertionError("Native pointer did not dispatch chat-edit click: "+selector+" "+point);}
  }
  /** Navigation outside the composer starts by dismissing the actual Android IME, as a user would. */
  static void hideKeyboard(Instrumentation test,WebView web)throws Exception{
    js(test,web,"(()=>{const active=document.activeElement;if(active&&typeof active.blur==='function')active.blur();return true;})()");
    test.runOnMainSync(()->{android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)web.getContext().getSystemService(Context.INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(web.getWindowToken(),0);});
    int[] view=new int[3];int previousHeight=-1;long stableSince=0;
    for(int i=0;i<60;i++){test.runOnMainSync(()->{Activity activity=(Activity)web.getContext();android.view.View decor=activity.getWindow().getDecorView();android.view.WindowInsets insets=decor.getRootWindowInsets();view[0]=web.getHeight();view[1]=web.getWidth();view[2]=android.os.Build.VERSION.SDK_INT>=30&&insets!=null&&(insets.isVisible(android.view.WindowInsets.Type.ime())||insets.getInsets(android.view.WindowInsets.Type.ime()).bottom>0)?1:0;});long now=SystemClock.elapsedRealtime();if(view[2]==0&&view[0]==previousHeight){if(stableSince==0)stableSince=now;if(now-stableSince>=300)return;}else stableSince=0;previousHeight=view[0];Thread.sleep(50);}
    throw new AssertionError("Android keyboard did not dismiss with stable native geometry: height="+view[0]+" width="+view[1]+" imeVisible="+view[2]);
  }
  static JSONObject keyboardGeometry(Instrumentation test,Activity activity,WebView web)throws Exception{
    JSONObject nativeView=new JSONObject();test.runOnMainSync(()->{try{android.view.View decor=activity.getWindow().getDecorView();int[] origin=new int[2],window=new int[2];web.getLocationOnScreen(origin);decor.getLocationOnScreen(window);android.view.WindowInsets insets=decor.getRootWindowInsets();int ime=insets==null?0:insets.getInsets(android.view.WindowInsets.Type.ime()).bottom;nativeView.put("webTop",origin[1]).put("webWidth",web.getWidth()).put("webHeight",web.getHeight()).put("windowBottom",window[1]+decor.getHeight()).put("imeHeight",ime).put("imeShown",insets!=null&&insets.isVisible(android.view.WindowInsets.Type.ime())&&ime>0).put("safeBottom",window[1]+decor.getHeight()-ime);}catch(Exception e){throw new IllegalStateException(e);}});
    JSONObject dom=new JSONObject(js(test,web,"(()=>{const rect=id=>{const r=document.getElementById(id).getBoundingClientRect();return {top:r.top,bottom:r.bottom};};return {innerWidth,innerHeight,visualHeight:visualViewport?visualViewport.height:innerHeight,input:rect('message-input'),send:rect('send'),card:rect('chat-edit-context')};})()"));double scale=nativeView.getDouble("webWidth")/dom.getDouble("innerWidth");return new JSONObject().put("native",nativeView).put("dom",dom).put("inputScreenBottom",nativeView.getDouble("webTop")+dom.getJSONObject("input").getDouble("bottom")*scale).put("sendScreenBottom",nativeView.getDouble("webTop")+dom.getJSONObject("send").getDouble("bottom")*scale);
  }
  static JSONObject showKeyboard(Instrumentation test,Activity activity,WebView web)throws Exception{
    hideKeyboard(test,web);tap(test,web,"#message-input");test.runOnMainSync(()->{android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE);keyboard.showSoftInput(web,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});
    int oldHeight=-1;long stableSince=0;JSONObject geometry=null;for(int i=0;i<60;i++){geometry=keyboardGeometry(test,activity,web);int height=geometry.getJSONObject("native").getInt("webHeight");long now=SystemClock.elapsedRealtime();if(geometry.getJSONObject("native").getBoolean("imeShown")&&height==oldHeight){if(stableSince==0)stableSince=now;if(now-stableSince>=300)return geometry;}else stableSince=0;oldHeight=height;Thread.sleep(100);}throw new AssertionError("Real attached-card IME did not show with stable native insets: "+geometry);
  }
  static Object nativeCall(Activity activity,String method,JSONObject args)throws Exception{Method call=MainActivity.class.getDeclaredMethod("call",String.class,JSONObject.class);call.setAccessible(true);try{return call.invoke(activity,method,args);}catch(InvocationTargetException e){if(e.getCause() instanceof Exception)throw (Exception)e.getCause();throw e;}}
  static final class Fixture implements AutoCloseable {
    final VoiceSupport.StoreScope scope;Fixture(Instrumentation test)throws Exception{scope=new VoiceSupport.StoreScope(test.getTargetContext());}
    @Override public void close()throws Exception{scope.close();}
  }
  /** Isolated test-AVD only. Preserve encrypted preference values without decrypting or printing them. */
  static final class ModelSettings implements AutoCloseable {
    final SharedPreferences prefs;final Map<String,?> saved;
    ModelSettings(Context activity,Context fixture,String url)throws Exception{prefs=activity.getSharedPreferences("settings",0);saved=new HashMap<>(prefs.getAll());check(prefs.edit().putString("baseUrl",url).putString("model","chat-edit-synthetic-model").putBoolean("vision",false).putBoolean("localOcr",false).putString("asrUrl",url+"/audio-must-never-upload").remove("apiKey").remove("asrKey").commit(),"Set an unauthenticated local model fixture");new Settings(fixture).save(new JSONObject().put("baseUrl",url).put("model","chat-edit-synthetic-model").put("vision",false).put("localOcr",false));}
    @Override public void close(){SharedPreferences.Editor editor=prefs.edit().clear();for(Map.Entry<String,?> item:saved.entrySet()){Object value=item.getValue();if(value instanceof String)editor.putString(item.getKey(),(String)value);else if(value instanceof Boolean)editor.putBoolean(item.getKey(),(Boolean)value);else if(value instanceof Integer)editor.putInt(item.getKey(),(Integer)value);else if(value instanceof Long)editor.putLong(item.getKey(),(Long)value);else if(value instanceof Float)editor.putFloat(item.getKey(),(Float)value);else if(value instanceof Set){Set<String> values=new HashSet<>();for(Object entry:(Set<?>)value){if(!(entry instanceof String))throw new IllegalStateException("Unknown existing preference set type");values.add((String)entry);}editor.putStringSet(item.getKey(),values);}else throw new IllegalStateException("Unknown existing preference type");}check(editor.commit(),"Restore the test device's prior encrypted preferences");}
  }
  static void cancelFixtureReminders(Context activity,Store db)throws Exception{JSONArray rows=db.all("memories");for(int i=0;i<rows.length();i++){JSONObject item=rows.getJSONObject(i);if(item.optLong("remindAt")>0||item.has("reminderSchedule")||item.has("reminderTime"))Scheduler.set(activity,new JSONObject().put("id",item.getString("id")).put("status","completed").put("remindAt",0));}}
  static JSONObject memory(Store db,String title,String text,String kind,String type)throws Exception{JSONObject source=db.message("user",text,new JSONArray(),id());JSONObject record=new JSONObject().put("id",id()).put("created",source.getLong("created")).put("title",title).put("content",text).put("kind",kind).put("type",type).put("status","active").put("truthState","current").put("sourceId",source.getString("id")).put("sourceIds",new JSONArray().put(source.getString("id"))).put("sourceAnchor",TimeAnchor.source(source)).put("files",new JSONArray()).put("tags",new JSONArray().put("合成测试"));db.put("memories",record);return db.one("memories",record.getString("id"));}
  interface Responder {String response(JSONObject request)throws Exception;}
  static final class ModelServer implements AutoCloseable {
    final ServerSocket socket;final Thread worker;final List<JSONObject> requests=Collections.synchronizedList(new ArrayList<>());final AtomicReference<Throwable> error=new AtomicReference<>();volatile Responder responder;volatile int status=200;
    ModelServer()throws Exception{socket=new ServerSocket(0,5,InetAddress.getByName("127.0.0.1"));worker=new Thread(()->{try{while(!socket.isClosed()){try(Socket client=socket.accept()){client.setSoTimeout(10000);InputStream in=client.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int last=0;while(header.size()<65536){int value=in.read();if(value<0)throw new EOFException("Model fixture header incomplete");header.write(value);last=(last<<8)|value;if(last==0x0d0a0d0a)break;}String fields=header.toString("US-ASCII");check(fields.startsWith("POST /chat/completions ")&&fields.toLowerCase(Locale.ROOT).contains("content-type: application/json"),"Only text chat reaches the local model fixture; no audio route");int length=-1;for(String line:fields.split("\\r\\n"))if(line.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(line.indexOf(':')+1).trim());check(length>=0&&length<2*1024*1024,"Bounded text model request");byte[] bytes=new byte[length];for(int offset=0;offset<length;){int count=in.read(bytes,offset,length-offset);if(count<0)throw new EOFException("Model fixture body incomplete");offset+=count;}JSONObject request=new JSONObject(new String(bytes,StandardCharsets.UTF_8));requests.add(request);String result=responder==null?"{}":responder.response(request);JSONObject body=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",result))));byte[] data=body.toString().getBytes(StandardCharsets.UTF_8);OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 "+status+" Fixture\r\nContent-Type: application/json\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(data);out.flush();}}}catch(Throwable e){if(!socket.isClosed())error.set(e);}},"chat-memory-edit-model-fixture");worker.setDaemon(true);worker.start();}
    String url(){return "http://127.0.0.1:"+socket.getLocalPort();}
    int count(){return requests.size();}
    void healthy(){check(error.get()==null,"Local model fixture error: "+error.get());}
    @Override public void close()throws Exception{socket.close();worker.join(2000);}
  }
}
